<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref,shallowRef,watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { api,errorText } from '../api'
import { useAuth } from '../stores/auth'
import { availableTaskCompanies,departmentsForCompany,listItems,validateAssignment } from '../domain'
import type { Row } from '../domain'
import { departmentReportOptions,selectedReportFields } from '../department-report'
const auth=useAuth(),router=useRouter(),form=ref<Row>({title:'',content:'',companyId:auth.me?.companyId,priority:'NORMAL',deadline:'',hostDeptId:'',collaboratorDeptIds:[],keyWork:false,customFields:[]}),departments=ref<Row[]>([]),collaborationDepartments=ref<Row[]>([]),assignmentReason=ref(''),match=ref<Row|null>(null),matchError=ref(''),error=ref(''),matching=ref(false),busy=ref(false),draftState=ref(''),loaded=ref(false),files=shallowRef<File[]>([]),uploadProgress=ref('')
const reportSelection=computed<string[]>({get:()=>(form.value.customFields??[]).map((f:Row)=>f.id),set:ids=>{form.value.customFields=selectedReportFields(ids)}})
const draftKey=`task-draft:${auth.me?.id}:${auth.me?.companyId}:${auth.me?.role}`
const companies=computed(()=>availableTaskCompanies(auth.me?.role??'',auth.me?.companyId,collaborationDepartments.value.length?collaborationDepartments.value:departments.value))
const hostDepartments=computed(()=>departmentsForCompany(form.value.companyId,departments.value))
const suggestionChanged=computed(()=>{const suggestions=match.value?.suggestions??[];if(!suggestions.length)return false;const host=suggestions.find((s:Row)=>s.role==='HOST');const collaborators=suggestions.filter((s:Row)=>s.role==='COLLABORATOR').map((s:Row)=>String(s.deptId)).sort();return String(host?.deptId)!==String(form.value.hostDeptId)||JSON.stringify(collaborators)!==JSON.stringify(form.value.collaboratorDeptIds.map(String).sort())})
let matchTimer:ReturnType<typeof setTimeout>,saveTimer:ReturnType<typeof setInterval>,sequence=0
async function fetchMatch(){if(form.value.title.length+form.value.content.length<3)return;const seq=++sequence;matching.value=true;matchError.value='';try{const result=await api.post('/tasks/match',{title:form.value.title,content:form.value.content,companyId:form.value.companyId});if(seq===sequence)match.value=result}catch(e){if(seq===sequence){matchError.value=errorText(e);match.value=null}}finally{if(seq===sequence)matching.value=false}}
watch(()=>form.value.companyId,(current,previous)=>{if(loaded.value&&String(current)!==String(previous))form.value.hostDeptId=''})
watch(()=>[form.value.title,form.value.content,form.value.companyId],()=>{clearTimeout(matchTimer);sequence++;matching.value=false;match.value=null;if(loaded.value)matchTimer=setTimeout(fetchMatch,300)})
function applySuggestion(s:Row){if(s.role==='HOST'||s.role==='MASTER'){form.value.hostDeptId=s.deptId;form.value.collaboratorDeptIds=form.value.collaboratorDeptIds.filter((id:string)=>id!==s.deptId)}else if(s.deptId!==form.value.hostDeptId&&!form.value.collaboratorDeptIds.includes(s.deptId))form.value.collaboratorDeptIds.push(s.deptId);else ElMessage.warning('不能与主办部门重复，或该部门已是协办')}
const attachmentTypes=['txt','pdf','png','jpg','jpeg','doc','xls','zip']
function fileSize(file:File){return file.size>=1024*1024?(file.size/1024/1024).toFixed(1)+' MB':Math.max(1,Math.ceil(file.size/1024))+' KB'}
function selectFiles(event:Event){const input=event.target as HTMLInputElement;const accepted=[...files.value],rejected:string[]=[];for(const file of Array.from(input.files||[])){const ext=file.name.split('.').at(-1)?.toLowerCase();if(!ext||!attachmentTypes.includes(ext)||file.size===0||file.size>10*1024*1024){rejected.push(file.name);continue}if(!accepted.some(existing=>existing.name===file.name&&existing.size===file.size&&existing.lastModified===file.lastModified))accepted.push(file)}files.value=accepted;input.value='';if(rejected.length)error.value='以下附件未加入：'+rejected.join('、')+'。仅支持页面列出的类型，每个不超过10MB'}
function removeFile(index:number){files.value=files.value.filter((_,i)=>i!==index)}
function saveDraft(){if(!form.value.title&&!form.value.content)return;try{sessionStorage.setItem(draftKey,JSON.stringify(form.value));draftState.value=`草稿已保存于本次浏览会话 ${new Date().toLocaleTimeString('zh-CN')}`}catch{draftState.value='浏览器无法保存草稿，请及时提交'}}
function clearDraft(){sessionStorage.removeItem(draftKey);draftState.value='本次草稿已清除'}
async function create(){if(busy.value)return;if(form.value.companyId==null||form.value.companyId===''){error.value='请选择任务所属公司';return}error.value=validateAssignment(form.value.hostDeptId,form.value.collaboratorDeptIds);if(error.value)return;if(!form.value.title.trim()||!form.value.content.trim()||!form.value.deadline){error.value='请完善任务标题、内容要求及截止时间';return}if(new Date(form.value.deadline).getTime()<=Date.now()){error.value='截止时间必须晚于当前时间';return}if(suggestionChanged.value&&!assignmentReason.value.trim()){error.value='请说明调整分配建议的原因';return}busy.value=true;error.value='';uploadProgress.value='正在创建任务';try{const result=await api.post('/tasks',form.value);const failed:string[]=[],pending:string[]=[];for(let i=0;i<files.value.length;i++){const file=files.value[i],data=new FormData();data.append('file',file,file.name);data.append('taskId',String(result.id));uploadProgress.value=`上传附件 ${i+1} / ${files.value.length}`;try{const saved=await api.upload(data);if(saved.scanStatus!=='CLEAN')pending.push(file.name)}catch(e){failed.push(file.name+'：'+errorText(e))}}if(match.value?.matchingResultId){try{await api.post('/matching/feedback',{taskId:result.id,matchingResultId:match.value.matchingResultId,reason:assignmentReason.value.trim()||(match.value.suggestions?.length?'采用职能建议':'未命中规则，人工指定责任部门')})}catch(e){ElMessage.warning('任务已创建，匹配反馈未保存：'+errorText(e))}}clearDraft();await router.replace('/tasks/'+result.id);if(failed.length)ElMessage.warning({message:`任务已创建，${failed.length} 个附件未上传：${failed.join('；')}。请在详情页“附件与版本”补传。`,duration:10000});else if(pending.length)ElMessage.warning({message:`任务已创建，${pending.length} 个附件等待安全检查，通过后方可下载。`,duration:8000});else ElMessage.success('任务已创建，请核对并确认分配')}catch(e){error.value=errorText(e)}finally{busy.value=false;uploadProgress.value=''}}
onMounted(async()=>{try{departments.value=listItems(await api.get('/organization/departments'));try{collaborationDepartments.value=listItems(await api.get('/organization/collaboration-departments'))}catch{collaborationDepartments.value=departments.value;matchError.value='暂时无法加载跨公司协办目录，可继续选择本公司部门'}const saved=sessionStorage.getItem(draftKey);if(saved){const parsed=JSON.parse(saved);if(parsed.companyId===auth.me?.companyId){form.value={...form.value,...parsed};draftState.value='已恢复本次会话草稿'}}}catch(e){error.value=errorText(e)}loaded.value=true;saveTimer=setInterval(saveDraft,30000)})
onBeforeUnmount(()=>{clearTimeout(matchTimer);clearInterval(saveTimer);sequence++})
</script>
<template><div class="backline"><router-link to="/collections?new=1">需要各部门自行填多行表格？发起部门填表 ↗</router-link></div><section class="page-heading"><div><p class="eyebrow">CREATE A TASK</p><h1>布置任务</h1><p class="muted">明确目标与责任，职能匹配提供建议，由您确认最终分配。</p></div><el-button @click="$router.back()">返回任务列表</el-button></section><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><div class="create-layout"><section class="panel"><div class="panel-heading"><h2><span class="section-number">01</span>任务基本信息</h2><small>带 * 为必填</small></div><el-form label-position="top" @submit.prevent="create"><el-form-item label="任务标题" required><el-input v-model="form.title" maxlength="200" show-word-limit placeholder="清晰描述要完成的工作目标"/></el-form-item><el-form-item label="内容与交付要求" required><el-input v-model="form.content" type="textarea" :rows="7" maxlength="10000" show-word-limit placeholder="请描述背景、工作要求、成果形式与验收标准"/><div class="creation-attachments"><div class="row-between"><b>任务附件（可选）</b><label class="creation-upload">＋ 选择附件<input type="file" multiple accept=".txt,.pdf,.png,.jpg,.jpeg,.doc,.xls,.zip" aria-label="任务附件" @change="selectFiles"/></label></div><p class="muted">创建任务后自动上传。支持 TXT、PDF、PNG、JPG、DOC、XLS、ZIP；每个文件最多10MB。仅文本草稿会保存在本次会话中，选定文件需重新选择。</p><ul v-if="files.length" class="selected-attachments"><li v-for="(file,index) in files" :key="file.name+':'+file.size+':'+file.lastModified"><span :title="file.name">{{ file.name }} · {{ fileSize(file) }}</span><el-button text type="danger" :disabled="busy" :aria-label="'移除附件 '+file.name" @click="removeFile(index)">移除</el-button></li></ul></div><div class="department-report-options"><p><b>接收部门需填报</b><span class="muted"> · 选择后，各部门在更新进度时分别填写</span></p><el-checkbox-group v-model="reportSelection"><el-checkbox v-for="option in departmentReportOptions" :key="option.id" :value="option.id">{{ option.name }}</el-checkbox></el-checkbox-group><small class="muted">不选择时使用普通进展说明；“时间要求”为文字填报项，主任务截止时间单独设置。</small></div></el-form-item><div class="form-grid"><el-form-item label="任务所属公司" required><el-select v-model="form.companyId"><el-option v-for="c in companies" :key="c.id" :value="c.id" :label="c.name"/></el-select></el-form-item><el-form-item label="优先级" required><el-select v-model="form.priority"><el-option label="低" value="LOW"/><el-option label="中" value="NORMAL"/><el-option label="高" value="HIGH"/></el-select></el-form-item><el-form-item label="截止时间（北京时间）" required><el-date-picker v-model="form.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" style="width:100%"/></el-form-item></div><div class="section-rule"/><h2><span class="section-number">02</span>责任分配</h2><p class="muted">主办部门恰好一个；协办部门可按需要添加多个。跨公司协办需由对方确认。</p><el-form-item label="主办部门" required><el-select v-model="form.hostDeptId" filterable placeholder="选择唯一主办部门"><el-option v-for="d in hostDepartments" :key="d.id" :value="d.id" :label="`${d.companyName||d.companyId||''} / ${d.name}`"/></el-select></el-form-item><el-form-item label="协办部门"><el-select v-model="form.collaboratorDeptIds" multiple filterable><el-option v-for="d in collaborationDepartments" :key="d.id" :disabled="d.id===form.hostDeptId" :value="d.id" :label="`${d.companyName||d.companyId||''} / ${d.name}`"/></el-select></el-form-item><p v-if="collaborationDepartments.some(d=>form.collaboratorDeptIds.includes(d.id)&&d.companyId!==form.companyId)" class="notice">包含跨公司协作，相关部门确认前将仅接收必要的协办信息。</p><el-form-item v-if="suggestionChanged" label="调整分配建议的原因" required><el-input v-model="assignmentReason" type="textarea" :rows="2" maxlength="1000" placeholder="说明实际职责或本次协作安排"/></el-form-item><div class="form-footer"><span class="muted">{{ draftState||'每30秒保存本次会话草稿' }}</span><el-button :disabled="busy" @click="saveDraft">保存草稿</el-button><el-button type="primary" native-type="submit" :loading="busy">{{ uploadProgress||'创建任务' }}</el-button></div></el-form></section><aside class="panel match-panel"><p class="eyebrow">FUNCTION MATCH</p><h2>职能匹配建议</h2><p class="muted">标题与内容变更后自动更新建议。建议只供参考，您可以手动调整。</p><div v-if="matching" role="status" class="loading">正在匹配职能…</div><el-alert v-else-if="matchError" :title="matchError+'；您仍可手动分配'" type="warning" :closable="false"/><div v-else-if="!match?.suggestions?.length" class="match-empty">填写任务信息后，这里将展示<br>命中职能、理由与规则版本。</div><div v-for="s in match?.suggestions||[]" :key="s.deptId" class="match-card"><div class="row-between"><b>{{ s.deptName }}</b><span class="score">{{ s.score }} 分</span></div><p>{{ ['HOST','MASTER'].includes(s.role)?'建议主办':'建议协办' }}</p><ul><li v-for="(r,i) in s.reasons" :key="i">{{ typeof r==='string'?r:JSON.stringify(r) }}</li></ul><el-button size="small" plain @click="applySuggestion(s)">采用建议</el-button></div><p v-if="match" class="scope-note">规则版本 {{ match.ruleVersion }} · 命中词、否定词与人工兜底以规则解释为准。</p><el-button text @click="fetchMatch">重新匹配</el-button></aside></div></template>

<style scoped>
.creation-attachments{width:100%;margin-top:14px;padding:14px;border:1px solid var(--line);border-radius:8px;background:var(--surface)}.creation-attachments .row-between{flex-wrap:wrap}.creation-attachments b{font-size:13px}.creation-attachments .muted{font-size:11px;line-height:1.6;margin:9px 0 0}.creation-upload{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:6px;padding:6px 10px;color:var(--brand);font-size:12px;font-weight:600;cursor:pointer}.creation-upload:hover{border-color:var(--brand);background:var(--accent-soft)}.creation-upload:focus-within{outline:2px solid var(--brand);outline-offset:2px}.creation-upload input{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}.selected-attachments{list-style:none;margin:10px 0 0;padding:0}.selected-attachments li{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:6px 0;border-top:1px solid var(--line)}.selected-attachments span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}
.department-report-options{width:100%;margin-top:14px;padding:14px;border:1px solid var(--line);border-radius:8px;background:var(--surface-muted)}.department-report-options p{font-size:12px;margin:0 0 8px}.department-report-options .el-checkbox-group{display:flex;flex-wrap:wrap;gap:0 14px}.department-report-options small{display:block;margin-top:8px;line-height:1.7}</style>
